#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* left;
    Node* right;
    Node(int d) : data(d), left(nullptr), right(nullptr) {}
};

Node* insert(Node* root, int value) {
    Node* fresh = new Node(value);
    if (root == nullptr) {
        return fresh;
    }
    Node* cur = root;
    while (true) {
        if (value < cur->data) {
            if (cur->left == nullptr) {
                cur->left = fresh;
                return root;
            }
            cur = cur->left;
        } else {
            if (cur->right == nullptr) {
                cur->right = fresh;
                return root;
            }
            cur = cur->right;
        }
    }
}

void destroy(Node* node) {
    if (node == nullptr) {
        return;
    }
    destroy(node->left);
    destroy(node->right);
    delete node;
}

int main() {
    Node* root = nullptr;
    root = insert(root, 50);
    root = insert(root, 30);
    root = insert(root, 70);
    root = insert(root, 20);
    root = insert(root, 40);
    root = insert(root, 60);
    cout << "Root: " << root->data << endl;
    destroy(root);
    return 0;
}
